import { NextResponse } from "next/server";
import { pool } from "@/app/lib/db";

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { part_name, make, model, year, vin, price, image_url } = body;

    if (!part_name || !make || !model || !price) {
      return NextResponse.json(
        { error: "جميع الحقول الأساسية مطلوبة" },
        { status: 400 }
      );
    }

    const [result] = await pool.execute(
      "INSERT INTO parts (part_name, make, model, year, vin, price, image_url) VALUES (?, ?, ?, ?, ?, ?, ?)",
      [
        part_name,
        make,
        model,
        year || null,
        vin || null,
        price,
        image_url || null,
      ]
    );

    return NextResponse.json({ message: "تمت إضافة القطعة بنجاح", result });
  } catch (error: any) {
    console.error("خطأ في إضافة القطعة:", error);
    return NextResponse.json(
      { error: "حدث خطأ أثناء إضافة القطعة" },
      { status: 500 }
    );
  }
}